I have enough to answer. The `search`→`rate` delay sits on the wire, and reservation is CPU-saturated with a small but real effect on its caller.

```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 AS med_ms, approx_quantile(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2 ORDER BY 1", "claim": "search's rate.Rate/GetRates client spans take ~2s median, while rate's server spans stay ~0.5ms."},
        {"kind": "trace", "sql": "SELECT 'abn' p, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND service_name='search' UNION ALL SELECT 'nor', count(*), approx_quantile(duration,0.5)/1e6 FROM normal_traces WHERE span_name='rate.Rate/GetRates' AND service_name='search'", "claim": "Search-to-rate call median rises from normal levels to about 2 seconds during the incident."},
        {"kind": "trace", "sql": "WITH slow AS (SELECT trace_id FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND service_name='search' AND duration>1e9 LIMIT 1) SELECT t.service_name, t.span_name, t.span_id, t.parent_span_id, t.duration/1e6 AS ms FROM abnormal_traces t JOIN slow USING(trace_id)", "claim": "In a slow trace, search's rate client span takes 2172ms while rate's server span takes 0.8ms."}
      ]
    },
    {
      "service": "reservation",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'abn' p, attr_k8s_pod_name pod, metric, avg(value) v, max(value) mx FROM abnormal_metrics WHERE service_name='reservation' AND metric='container.cpu.usage' GROUP BY 1,2,3 UNION ALL SELECT 'nor', attr_k8s_pod_name, metric, avg(value), max(value) FROM normal_metrics WHERE service_name='reservation' AND metric='container.cpu.usage' GROUP BY 1,2,3", "claim": "Reservation container CPU rises from about 0.006 to about 3.3 cores, pinned at its limit."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3 UNION ALL SELECT 'nor', service_name, span_name, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3", "claim": "Frontend-facing CheckAvailability calls to reservation get slower (p95 about 2.1ms to 2.9ms), a smaller but real knock-on effect."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name IN ('search','rate') AND span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY 1,2 ORDER BY 1,2", "claim": "The slow rate call is the dominant cost of search.Search/Nearby, which has p95 about 2.7s while search's own geo call stays at 0.5ms."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='HTTP /hotels' GROUP BY 1,2,3 UNION ALL SELECT 'nor', service_name, span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='HTTP /hotels' GROUP BY 1,2,3", "claim": "User-facing frontend HTTP /hotels p95 rises from about 17ms to about 2.7s, matching the search delay."}
      ]
    },
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3 UNION ALL SELECT 'nor', service_name, span_name, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3", "claim": "Frontend's calls to reservation's CheckAvailability get slower as reservation's CPU saturates."}
      ]
    }
  ]
}
